import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        k = int(next(iterator))
        s = next(iterator)

        chars = list(s)
        i = 0

        while k > 0 and i < n:
            current_char = chars[i]

            if current_char == 'a':
                i += 1
                continue

            if current_char == 'b':
                target = 'a'
            else:
                target = chr(ord(current_char) - 1)

            count = 0
            j = i
            while j < n and chars[j] == current_char:
                count += 1
                j += 1

            if count <= k:
                for idx in range(i, j):
                    chars[idx] = target
                k -= count
                i = j
            else:
                break

        results.append("".join(chars))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
